import { describe, expect, it } from 'vitest'
import { formatReferences } from './list.js'

const MESSY_WALTERS =
  'Walters, W.H. & Wilder, E.I (2023) Fabrication and errors in the bibliographic citations generated by ChatGPT. Scientific Reports 13(1) 14045 doi:10.1038/s41598-023-41032-5'
const GRADY_APA =
  'Grady, J. S., Her, M., Moreno, G., Perez, C., & Yelinek, J. (2019). Emotions in storybooks: A comparison of storybooks that represent ethnic and racial groups in the United States. Psychology of Popular Media Culture, 8(3), 207–217. https://doi.org/10.1037/ppm0000185'
const BOOK =
  'Sugiyono. (2017). Metode penelitian kuantitatif, kualitatif, dan R&D. Bandung: Alfabeta.'
const WANTORO =
  'Wantoro, A., et al. (2025). Evaluasi Kinerja Algoritma Machine Learning (ML) Menggunakan Seleksi Fitur Pada Klasifikasi Diabetes. JIP (Jurnal Inform. Polinema), 11(3).'

const opts = (over: Partial<Parameters<typeof formatReferences>[1]> = {}) => ({
  style: 'apa' as const,
  sentenceCase: false,
  sort: false,
  ...over,
})

describe('formatReferences: one reference', () => {
  it('rewrites a careless reference and lists only the parts that changed, before and after', () => {
    const [item] = formatReferences([MESSY_WALTERS], opts())
    expect(item).toMatchObject({
      index: 0,
      status: 'changed',
      reason: null,
      label: null,
      text: 'Walters, W. H., & Wilder, E. I. (2023). Fabrication and errors in the bibliographic citations generated by ChatGPT. Scientific Reports, 13(1), Article 14045. https://doi.org/10.1038/s41598-023-41032-5',
    })
    expect(item?.changes).toEqual([
      { field: 'authors', before: 'Walters, W.H. & Wilder, E.I', after: 'Walters, W. H., & Wilder, E. I.' },
      { field: 'year', before: '(2023)', after: '(2023).' },
      {
        field: 'source',
        before: 'Scientific Reports 13(1) 14045',
        after: 'Scientific Reports, 13(1), Article 14045.',
      },
      {
        field: 'doi',
        before: 'doi:10.1038/s41598-023-41032-5',
        after: 'https://doi.org/10.1038/s41598-023-41032-5',
      },
    ])
  })

  it('says a reference already matches the style when nothing would change', () => {
    const [item] = formatReferences([GRADY_APA], opts())
    expect(item).toMatchObject({ status: 'same', changes: [], text: GRADY_APA })
  })

  it('does not call the same reference matching in another style', () => {
    const [item] = formatReferences([GRADY_APA], opts({ style: 'ieee' }))
    expect(item?.status).toBe('changed')
    expect(item?.text.startsWith('J. S. Grady, M. Her, G. Moreno, C. Perez, and J. Yelinek, "')).toBe(
      true,
    )
  })

  it('reads a reference written in one style and writes it in another', () => {
    const ieee = formatReferences([MESSY_WALTERS], opts({ style: 'ieee' }))[0]
    const back = formatReferences([ieee?.text ?? ''], opts({ style: 'apa' }))[0]
    expect(back?.text).toBe(formatReferences([MESSY_WALTERS], opts())[0]?.text)
  })

  it('does not rewrite what it cannot read as a journal article, and says why', () => {
    const [book, junk] = formatReferences([BOOK, 'asdf qwer'], opts())
    expect(book).toMatchObject({
      status: 'not_rewritten',
      reason: 'not_journal_article',
      text: BOOK,
      changes: [],
    })
    expect(junk).toMatchObject({ status: 'not_rewritten', reason: 'unreadable', text: 'asdf qwer' })
  })

  it('still cleans the list number and the DOI of a reference it does not rewrite', () => {
    const [item] = formatReferences(['3. Sugiyono. (2017). Metode. Bandung: Alfabeta. doi:10.1000/abc'], opts())
    expect(item?.text).toBe('Sugiyono. (2017). Metode. Bandung: Alfabeta. https://doi.org/10.1000/abc')
  })

  it('leaves empty entries out', () => {
    expect(formatReferences(['', '   ', GRADY_APA], opts())).toHaveLength(1)
    expect(formatReferences([], opts())).toEqual([])
  })
})

describe('formatReferences: the article that was read', () => {
  it('carries the journal article it read, for making a .bib, and nothing for what it did not rewrite', () => {
    const [a, b] = formatReferences([GRADY_APA, BOOK], opts())
    expect(a?.article).toMatchObject({ year: '2019', journal: 'Psychology of Popular Media Culture', doi: '10.1037/ppm0000185' })
    expect(a?.article?.authors.map((p) => p.family)).toEqual(['Grady', 'Her', 'Moreno', 'Perez', 'Yelinek'])
    expect(b?.article).toBeNull()
  })

  it('is the same whichever style the text is written in', () => {
    const apa = formatReferences([GRADY_APA], opts())[0]?.article
    const ieee = formatReferences([GRADY_APA], opts({ style: 'ieee' }))[0]?.article
    expect(ieee).toEqual(apa)
  })
})

describe('formatReferences: notes', () => {
  it('gives the notes that go with a reference', () => {
    const apa = formatReferences([WANTORO], opts())[0]
    expect(apa?.notes).toEqual(['et_al_kept', 'title_case'])
    const ieee = formatReferences([WANTORO], opts({ style: 'ieee' }))[0]
    expect(ieee?.notes).toEqual(['et_al_kept', 'title_case', 'ieee_journal_abbreviation'])
  })

  it('swaps the title note for the sentence-case note when that option is on', () => {
    const r = formatReferences([WANTORO], opts({ sentenceCase: true }))[0]
    expect(r?.notes).toEqual(['et_al_kept', 'sentence_case_applied'])
    expect(r?.text).toContain('Evaluasi kinerja algoritma machine learning (ML) menggunakan')
  })

  it('says when the order of a name was guessed', () => {
    const r = formatReferences(
      ['Agus Wantoro and Aviv Fitria Yulia (2025). Sebuah judul. Jurnal X, 1(1), 1-2.'],
      opts(),
    )[0]
    expect(r?.notes).toContain('names_uncertain')
  })

  it('has no notes for a reference it does not rewrite', () => {
    expect(formatReferences([BOOK], opts({ style: 'ieee' }))[0]?.notes).toEqual([])
  })
})

describe('formatReferences: order and numbering', () => {
  const A = 'Zulkifli, A. (2020). Judul satu. Jurnal Satu, 1(1), 1-2.'
  const B = 'Aaron, B. (2021). Judul dua. Jurnal Dua, 2(1), 3-4.'
  const C = 'Moreno, G. (2019). Judul tiga. Jurnal Tiga, 3(1), 5-6.'

  it('keeps the order it was given by default', () => {
    expect(formatReferences([A, B, C], opts()).map((i) => i.index)).toEqual([0, 1, 2])
  })

  it('sorts APA and Harvard by the first author when asked, and remembers where each came from', () => {
    for (const style of ['apa', 'harvard'] as const) {
      const items = formatReferences([A, B, C], opts({ style, sort: true }))
      expect(items.map((i) => i.index)).toEqual([1, 2, 0])
    }
  })

  it('sorts by year when the first author is the same', () => {
    const [x, y] = [
      'Doe, J. (2022). B. Jurnal, 1(1), 1-2.',
      'Doe, J. (2019). A. Jurnal, 1(1), 1-2.',
    ]
    expect(
      formatReferences([x as string, y as string], opts({ sort: true })).map((i) => i.index),
    ).toEqual([1, 0])
  })

  it('puts what it could not read in its place by its own text', () => {
    const items = formatReferences([A, BOOK, B], opts({ sort: true }))
    expect(items.map((i) => i.index)).toEqual([2, 1, 0]) // Aaron, Sugiyono, Zulkifli
  })

  it('numbers IEEE references in the order given and never sorts them', () => {
    const items = formatReferences([A, B, C], opts({ style: 'ieee', sort: true }))
    expect(items.map((i) => i.index)).toEqual([0, 1, 2])
    expect(items.map((i) => i.label)).toEqual(['[1]', '[2]', '[3]'])
  })

  it('does not number APA or Harvard references', () => {
    expect(formatReferences([A, B], opts({ style: 'harvard' })).map((i) => i.label)).toEqual([
      null,
      null,
    ])
  })
})
